function renderInfoPanel(){const e=currentPhoto.edits;const meta=`<div class="info-grid"><div class="info-cell"><small>Filename</small>${esc(currentPhoto.name)}</div><div class="info-cell"><small>Dimensions</small>${currentPhoto.width} × ${currentPhoto.height}</div><div class="info-cell"><small>File type</small>${esc(currentPhoto.type||'Unknown')}</div><div class="info-cell"><small>File size</small>${fmtBytes(currentPhoto.size)}</div><div class="info-cell"><small>Imported</small>${new Date(currentPhoto.created).toLocaleString()}</div><div class="info-cell"><small>Rating</small>${currentPhoto.rating||'Unrated'}</div></div><div class="metadata-edit"><label>Caption<textarea id="photoCaption" maxlength="1000" placeholder="Add a local caption">${esc(currentPhoto.caption||'')}</textarea></label><label>Keywords<input id="photoKeywords" value="${esc((currentPhoto.keywords||[]).join(', '))}" placeholder="travel, portrait, sunset"></label></div>`;const diag=`<div class="info-grid"><div class="info-cell"><small>Renderer</small>Canvas pixel pipeline</div><div class="info-cell"><small>Acceleration</small>${navigator.gpu?'WebGPU available':'CPU/WASM fallback'}</div><div class="info-cell"><small>Local masks</small>${currentPhoto.localEdits.length}</div><div class="info-cell"><small>Remove operations</small>${currentPhoto.healOps.length}</div></div><div class="diagnostic-buttons"><button data-diagnostic="none">Off</button><button data-diagnostic="highlights">Highlight Clip</button><button data-diagnostic="shadows">Shadow Clip</button><button data-diagnostic="focus">Focus Peaking</button></div><label class="solo-toggle"><input id="soloSections" type="checkbox" ${soloSections?'checked':''}> Solo section mode</label>`;return accordionSection('metadata','Metadata',meta,'quick')+accordionSection('diagnostics','Diagnostics',diag,'pro')}
 function renderControls(){if(!currentPhoto)return;applyEditorMode(false);const panels={edit:renderEditPanel,masks:renderMasksPanel,heal:renderHealPanel,transform:renderTransformPanel,retouch:renderRetouchPanel,ai:renderAIPanel,layers:renderLayersPanel,info:renderInfoPanel};const rail=$('#toolTabs');rail.classList.add('tool-accordion');rail.innerHTML=TOOL_META.filter(t=>modeAllows(t.tier)).map(t=>{const open=isTopToolOpen(t.id);return `<section class="tool-section ${open?'open':''}" data-tool-section="${t.id}"><button class="tool-section-header" type="button" data-tool-toggle="${t.id}"><span class="tool-section-icon">${t.icon}</span><b>${t.label}</b><span class="tool-chevron">⌄</span></button><div class="tool-section-body">${open?(panels[t.id]||renderEditPanel)():''}</div></section>`}).join('');$('#controls').innerHTML='';$('#controls').classList.add('hidden');$$('[data-tool-toggle]').forEach(b=>b.onclick=()=>{const id=b.dataset.toolToggle,sec=b.closest('.tool-section'),open=!sec.classList.contains('open');setTopToolOpen(id,open);currentPanel=id;renderControls()});bindAccordions();bindGeneratedControls();drawMaskOverlay();drawToneCurve?.()}
