  const prompt=prompt('Describe the object to select','main object')?.trim();if(!prompt)return;
  toast(`Finding “${prompt}” locally…`);
  if(typeof DarkRoomAI!=='undefined'&&DarkRoomAI.objectBox){try{const found=await DarkRoomAI.objectBox(photoBlob(currentPhoto),prompt);if(found?.box){const w=currentPhoto.width||1,h=currentPhoto.height||1,m=newMask('box',`Object: ${prompt}`);m.box={xmin:Math.max(0,found.box.xmin/w),ymin:Math.max(0,found.box.ymin/h),xmax:Math.min(1,found.box.xmax/w),ymax:Math.min(1,found.box.ymax/h)};m.source='zero-shot object detection';captureHistory();currentPhoto.localEdits.push(m);activeLocalId=m.id;captureHistory();renderControls();await renderCanvas($('#editorCanvas'));debouncedSave();toast(`Object selected · ${Math.round((found.score||0)*100)}%`);return}}catch(e){console.warn('Object detector fallback',e)}}
  type='subject';
