async function createAlbum(){const name=$('#albumName').value.trim();if(!name)return;await put('albums',{id:uid(),name,created:Date.now()});hideAlbumModal();await refreshData();toast('Album created')}
async function renameAlbum(){const a=albums.find(x=>x.id===currentAlbumId);if(!a)return;const name=prompt('Rename album',a.name)?.trim();if(!name)return;a.name=name;await put('albums',a);await refreshData();toast('Album renamed')}
async function deleteAlbum(){const a=albums.find(x=>x.id===currentAlbumId);if(!a||!confirm(`Delete album “${a.name}”? Photos will stay in your library.`))return;for(const p of albumPhotos(a.id)){p.albumIds=p.albumIds.filter(id=>id!==a.id);await put('photos',p)}await del('albums',a.id);currentAlbumId=null;route('albums');await refreshData();toast('Album deleted')}
function setFlag(flag){captureHistory();currentPhoto.flag=currentPhoto.flag===flag?'none':flag;captureHistory();syncEditorMeta();debouncedSave()}
async function enterPhotoOnly(native=true){if(!currentPhoto||photoOnly)return;photoOnly=true;$('#editor').classList.add('photo-only');$('#fullscreenBtn').classList.add('active');resetZoom();syncEditorMeta();await new Promise(requestAnimationFrame);await renderCanvas($('#editorCanvas'));if(native&&document.documentElement.requestFullscreen){try{await document.documentElement.requestFullscreen()}catch{}}}
async function exitPhotoOnly(native=true){if(!photoOnly)return;photoOnly=false;$('#editor').classList.remove('photo-only');$('#fullscreenBtn').classList.remove('active');syncEditorMeta();if(native&&document.fullscreenElement){try{await document.exitFullscreen()}catch{}}}
function togglePhotoOnly(force){if(force===false)return exitPhotoOnly();return photoOnly?exitPhotoOnly():enterPhotoOnly()}
document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement&&photoOnly){photoOnly=false;$('#editor').classList.remove('photo-only');$('#fullscreenBtn').classList.remove('active');syncEditorMeta()}})
function initZoom(){const vp=$('#photoViewport');vp.addEventListener('wheel',e=>{if(paintMode)return;e.preventDefault();zoom=Math.max(.25,Math.min(8,zoom*(e.deltaY<0?1.12:.89)));applyTransform()},{passive:false});vp.addEventListener('pointerdown',e=>{if(e.target.closest?.('button,input,select,textarea,a,[role=button]'))return;if(beginPaint(e)){vp.setPointerCapture?.(e.pointerId);return}if(e.pointerType==='touch')return;drag={x:e.clientX-panX,y:e.clientY-panY};vp.setPointerCapture?.(e.pointerId)});vp.addEventListener('pointermove',e=>{if(paintMode){continuePaint(e);return}if(!drag)return;panX=e.clientX-drag.x;panY=e.clientY-drag.y;applyTransform()});vp.addEventListener('pointerup',()=>{if(paintMode)endPaint();drag=null});vp.addEventListener('pointercancel',()=>{if(paintMode)endPaint();drag=null});vp.addEventListener('touchstart',e=>{if(paintMode)return;if(e.touches.length===1)drag={x:e.touches[0].clientX-panX,y:e.touches[0].clientY-panY};if(e.touches.length===2){const[a,b]=e.touches;pinch={d:Math.hypot(a.clientX-b.clientX,a.clientY-b.clientY),z:zoom};drag=null}},{passive:true});vp.addEventListener('touchmove',e=>{if(paintMode)return;if(e.touches.length===1&&drag){panX=e.touches[0].clientX-drag.x;panY=e.touches[0].clientY-drag.y;applyTransform()}if(e.touches.length===2&&pinch){const[a,b]=e.touches,d=Math.hypot(a.clientX-b.clientX,a.clientY-b.clientY);zoom=Math.max(.25,Math.min(8,pinch.z*d/pinch.d));applyTransform()}},{passive:true});vp.addEventListener('touchend',()=>{drag=null;pinch=null});vp.ondblclick=()=>{if(paintMode)return;zoom=zoom===1?2:1;panX=panY=0;applyTransform()}}
 document.addEventListener('dblclick',e=>{const r=e.target;if(!r.matches?.('input[type="range"][data-edit]'))return;const key=r.dataset.edit,value=defaultEdits()[key]??0;r.value=value;r.dispatchEvent(new Event('input',{bubbles:true}));r.dispatchEvent(new Event('change',{bubbles:true}));toast(`${key} reset`)})
const beginPaintDefault=beginPaint;beginPaint=function(e){if(paintMode==='quick-select'){const p=pointOnCanvas(e);if(p.x<0||p.x>1||p.y<0||p.y>1)return false;captureHistory();const m=newMask('radial','Selected area',{exposure:18});m.cx=p.x;m.cy=p.y;m.rx=.22;m.ry=.22;currentPhoto.localEdits.push(m);activeLocalId=m.id;paintMode=null;renderControls();renderCanvas($('#editorCanvas'));debouncedSave();toast('Area selected — adjust the mask or paint to refine');return true}return beginPaintDefault(e)};
document.addEventListener('click',e=>{if(e.target.matches?.('#quickMaskSelect')){paintMode='quick-select';$('#photoViewport').classList.add('painting');$('#paintHud').classList.remove('hidden');$('#paintHud b').textContent='Click a region';$('#paintHud span').textContent='Click the photo to create a local mask'}})

// Every slider also accepts a precise numeric value. Event delegation keeps this
// working when accordion panels are re-rendered after each edit.
document.addEventListener('input',e=>{const n=e.target.closest?.('.control-number');if(!n)return;const [attr,key]=(n.dataset.controlNumber||'edit|').split('|'),range=document.querySelector(`input[data-${attr}="${key}"]`);if(!range)return;const min=Number(range.min),max=Number(range.max),raw=Number(n.value);if(!Number.isFinite(raw))return;const value=Math.max(min,Math.min(max,raw));n.value=String(value);range.value=String(value);range.dispatchEvent(new Event('input',{bubbles:true}))});
document.addEventListener('input',e=>{const r=e.target;if(!r.matches?.('input[type="range"][data-edit],input[type="range"][data-local-edit],input[type="range"][data-layer-edit]'))return;const attr=r.dataset.edit!==undefined?'edit':r.dataset.localEdit!==undefined?'local-edit':'layer-edit';const key=r.dataset.edit??r.dataset.localEdit??r.dataset.layerEdit;const n=document.querySelector(`[data-control-number="${attr}|${key}"]`);if(n)n.value=r.value});
document.addEventListener('change',e=>{const n=e.target.closest?.('.control-number');if(!n)return;const [attr,key]=(n.dataset.controlNumber||'edit|').split('|'),range=document.querySelector(`input[data-${attr}="${key}"]`);if(!range)return;captureHistory();range.dispatchEvent(new Event('change',{bubbles:true}));debouncedSave()});

// Point-curve editor: the curve is the source of truth while the five tonal
// sliders remain synchronized views of the curve at Lightroom-style regions.
let curveDragV2=null;
const CURVE_PAD=20;
function drawToneCurvePointEditor(){const c=$('#toneCurveCanvas');if(!c||!currentPhoto)return;const x=c.getContext('2d'),w=c.width,h=c.height,p=CURVE_PAD,points=curvePointsForEdit();x.clearRect(0,0,w,h);x.fillStyle='#121214';x.fillRect(0,0,w,h);x.strokeStyle='#36363b';x.lineWidth=1;for(let i=0;i<=4;i++){const q=p+(w-p*2)*i/4,r=p+(h-p*2)*i/4;x.beginPath();x.moveTo(q,p);x.lineTo(q,h-p);x.moveTo(p,r);x.lineTo(w-p,r);x.stroke()}x.save();x.setLineDash([4,4]);x.strokeStyle='#777';x.beginPath();x.moveTo(p,h-p);x.lineTo(w-p,p);x.stroke();x.restore();x.strokeStyle='#b88cff';x.lineWidth=2.5;x.beginPath();for(let i=0;i<=192;i++){const l=i/192,v=curveValueAt(points,l),px=p+l*(w-p*2),py=h-p-v*(h-p*2);i?x.lineTo(px,py):x.moveTo(px,py)}x.stroke();points.forEach(point=>{const px=p+point.x*(w-p*2),py=h-p-point.y*(h-p*2),drag=curveDragV2?.point,active=!!drag&&Math.abs(point.x-drag.x)<.0001&&Math.abs(point.y-drag.y)<.0001;x.beginPath();x.arc(px,py,active?6:4.5,0,Math.PI*2);x.fillStyle=active?'#b88cff':'#f1f1f1';x.fill();x.strokeStyle='#0c0c0d';x.lineWidth=1;x.stroke()})}
drawToneCurve=drawToneCurvePointEditor;
function curveEventPosition(c,e){const r=c.getBoundingClientRect(),px=(e.clientX-r.left)*c.width/Math.max(1,r.width),py=(e.clientY-r.top)*c.height/Math.max(1,r.height),pw=Math.max(1,c.width-CURVE_PAD*2),ph=Math.max(1,c.height-CURVE_PAD*2);return{x:Math.max(0,Math.min(1,(px-CURVE_PAD)/pw)),y:Math.max(0,Math.min(1,1-(py-CURVE_PAD)/ph))}}
function curvePointIndex(points,x,y,c){const r=c.getBoundingClientRect(),pw=c.width-CURVE_PAD*2,ph=c.height-CURVE_PAD*2,px=(CURVE_PAD+x*pw)/c.width*r.width,py=(CURVE_PAD+(1-y)*ph)/c.height*r.height;let best=-1,d=15;for(let i=0;i<points.length;i++){const qx=(CURVE_PAD+points[i].x*pw)/c.width*r.width,qy=(CURVE_PAD+(1-points[i].y)*ph)/c.height*r.height,dist=Math.hypot(px-qx,py-qy);if(dist<d){best=i;d=dist}}return best}
document.addEventListener('pointerdown',e=>{const c=e.target.closest?.('#toneCurveCanvas');if(!c)return;e.preventDefault();e.stopPropagation();const pos=curveEventPosition(c,e),points=ensureCurvePoints();let index=curvePointIndex(points,pos.x,pos.y,c);if(index<0){const point={x:pos.x,y:pos.y};points.push(point);points.sort((a,b)=>a.x-b.x);currentPhoto.edits.curvePoints=[...points];index=currentPhoto.edits.curvePoints.findIndex(p=>p===point);syncCurveSlidersFromPoints(currentPhoto.edits.curvePoints)}curveDragV2={canvas:c,point:currentPhoto.edits.curvePoints[index]};c.setPointerCapture?.(e.pointerId);drawToneCurve()},true);
document.addEventListener('pointermove',e=>{const d=curveDragV2;if(!d)return;e.preventDefault();e.stopPropagation();const pos=curveEventPosition(d.canvas,e),points=currentPhoto?.edits?.curvePoints,index=points?.indexOf(d.point);if(index===undefined||index<0)return;const first=index===0,last=index===points.length-1,min=first?0:points[index-1].x+.005,max=last?1:points[index+1].x-.005,point={x:first?0:last?1:Math.max(min,Math.min(max,pos.x)),y:pos.y},next=points.map((p,i)=>i===index?point:p).sort((a,b)=>a.x-b.x);currentPhoto.edits.curvePoints=next;d.point=point;syncCurveSlidersFromPoints(next);drawToneCurve();renderCanvas($('#editorCanvas'))},true);
document.addEventListener('pointerup',e=>{if(!curveDragV2)return;e.preventDefault();e.stopPropagation();captureHistory();debouncedSave();curveDragV2=null;drawToneCurve()},true);
document.addEventListener('dblclick',e=>{const c=e.target.closest?.('#toneCurveCanvas');if(!c||!currentPhoto)return;e.preventDefault();e.stopPropagation();const pos=curveEventPosition(c,e),points=ensureCurvePoints(),index=curvePointIndex(points,pos.x,pos.y,c);if(index>0&&index<points.length-1){captureHistory();points.splice(index,1);currentPhoto.edits.curvePoints=points;syncCurveSlidersFromPoints(points);captureHistory();drawToneCurve();renderCanvas($('#editorCanvas'));debouncedSave();toast('Curve point removed')}},true);
